#!/usr/bin/env bash
# Build the book, generating the pages derived from the studies first.
#
# The PCS frontier page is generated by ragu-pcs/pareto-model.py, which writes the standalone
# page beside itself and, for the book, the page in four files: the HTML that the chapter
# includes, a stylesheet, a script and the data as a script. They are generated here rather than
# committed, since each regeneration would add ten megabytes to the history. mdbook copies files
# other than Markdown from src/ into the output unchanged, so the stylesheet, script and data are
# served beside the chapter that includes the HTML.
#
# Run from anywhere; the book lands in book/book. `PYTHON` overrides the interpreter.
set -euo pipefail
cd "$(dirname "$0")/.."

# The prose is hard-wrapped at 100 columns; `python scripts/wrap-prose.py --write` refills what
# is not, and the check fails the build on a line that it would have shortened.
"${PYTHON:-python3}" scripts/wrap-prose.py --check

# A figure is joined to its unit by a no-break space, so that the two do not part at a line
# break; `python scripts/nbsp-units.py --write` puts in the ones that are missing.
"${PYTHON:-python3}" scripts/nbsp-units.py --check

# The model prints its summary line first, then every point; only the summary is shown. It
# fails when a figure quoted in the tracked prose is stale against the model, or a claim the
# prose makes no longer holds; `python ragu-pcs/pareto-model.py --fill` refreshes the figures.
"${PYTHON:-python3}" ragu-pcs/pareto-model.py | sed -n 1p
cp ragu-pcs/pareto-book.html ragu-pcs/pareto.css ragu-pcs/pareto.js ragu-pcs/pareto-data.js book/src/proof-systems/

# Run from within book/ so the todo preprocessor's relative command path resolves.
cd book && mdbook build
